S = "Hakeem Force Academy"
QS = [
(S, "Who were the four Rightly Guided Caliphs (Khulafa-e-Rashideen) of Islam, in order?", ["Abu Bakr, Umar, Uthman, Ali (RA)", "Umar, Abu Bakr, Ali, Uthman (RA)", "Abu Bakr, Uthman, Umar, Ali (RA)", "Abu Bakr, Umar, Ali, Uthman (RA)"], 0, "After the Holy Prophet (PBUH), the caliphs were Hazrat Abu Bakr, Hazrat Umar, Hazrat Uthman and Hazrat Ali (RA) in that order.", "Their combined rule lasted about 30 years, from 632 AD to 661 AD.", [1383]),
(S, "What is the value of iota multiplied by iota (i x i)?", ["1", "-1", "i", "0"], 1, "Iota (i) is defined as the square root of -1. So i x i = i squared = -1.", "Powers of i repeat in a cycle of four: i, -1, -i, 1.", [1062]),
(S, "What is iota (i) in mathematics?", ["The square root of -1 (imaginary unit)", "The square root of 1", "A prime number", "The value of pi"], 0, "Iota is the imaginary unit and is defined as i = square root of -1, so i squared = -1.", "Numbers of the form a + ib are called complex numbers.", [623]),
(S, "Why did the USA enter World War I in 1917?", ["Because of unrestricted German submarine warfare and the Zimmermann Telegram", "Because Japan attacked Pearl Harbor", "Because Britain invaded Mexico", "Because of the Russian Revolution"], 0, "Germany resumed unrestricted submarine warfare, sinking American ships, and the Zimmermann Telegram proposed a German alliance with Mexico against the USA. The USA declared war on Germany in April 1917.", "President Woodrow Wilson asked Congress for the declaration of war.", [4832]),
(S, "In which year did the USA and its allies invade Iraq?", ["1991", "2001", "2003", "2005"], 2, "The US-led invasion of Iraq began in 2003 to remove the government of Saddam Hussein.", "The 1991 Gulf War was a different conflict, fought after Iraq invaded Kuwait.", [2253, 2290]),
(S, "On which date did the US-led invasion of Iraq begin?", ["11 September 2001", "20 March 2003", "7 October 2001", "1 May 2003"], 1, "The US-led coalition began the invasion of Iraq on 20 March 2003 (19 March in US time).", "President George W. Bush declared the end of major combat on 1 May 2003.", [2460]),
(S, "In which years did the USA invade Afghanistan and Iraq respectively?", ["2003 and 2001", "2001 and 2003", "1999 and 2003", "2001 and 2005"], 1, "The USA invaded Afghanistan in October 2001 after the 9/11 attacks and invaded Iraq in March 2003.", "The USA withdrew its forces from Afghanistan in August 2021.", [3627]),
(S, "Who is the current President of Iraq (as of October 2026)?", ["Nizar Amidi", "Abdul Latif Rashid", "Barham Salih", "Fuad Masum"], 0, "Iraq's parliament elected Nizar Amidi (Amedi) as President on 11 April 2026.", "His predecessor Abdul Latif Rashid held the office from October 2022 to 2026.", [510]),
(S, "What is the full form of ISPR?", ["Inter Services Public Relations", "Inter Service Press Reporting", "Internal Security and Public Relations", "International Services Public Reports"], 0, "ISPR stands for Inter Services Public Relations, the media wing of the Pakistan Armed Forces.", "It is headed by a Director General, a serving army officer.", [142, 2958, 1105]),
(S, "On which date was the state of Israel declared (its independence date)?", ["14 May 1948", "15 August 1947", "5 June 1967", "1 January 1950"], 0, "David Ben-Gurion declared the state of Israel on 14 May 1948, as the British Mandate ended.", "Israel marks Independence Day by the Hebrew calendar (5 Iyar), so its Gregorian date changes each year.", [2468, 2480, 321, 2378, 3634]),
(S, "In which year AD did Abu Jahl die at the Battle of Badr?", ["622 AD", "623 AD", "624 AD", "630 AD"], 2, "The Battle of Badr was fought on 17 Ramadan 2 AH, which is March 624 AD, and Abu Jahl was killed in it.", "Two young Ansari boys, Muadh and Muawwidh, killed him.", [2245]),
(S, "Where is the historic Jamrud Fort located?", ["Peshawar, at the entrance of the Khyber Pass", "Lahore", "Quetta", "Multan"], 0, "Jamrud Fort stands near Peshawar at the eastern mouth of the Khyber Pass in Khyber Pakhtunkhwa. It was built in 1836 by the Sikh general Hari Singh Nalwa.", "Hari Singh Nalwa was killed in a battle at Jamrud in 1837.", [3150, 3732]),
(S, "What is the capital of Japan?", ["Osaka", "Kyoto", "Tokyo", "Hiroshima"], 2, "Tokyo is the capital and largest city of Japan.", "Kyoto was the old imperial capital of Japan until 1868.", [1083]),
(S, "Choose the correct word: There is ____ water in a jar.", ["many", "several", "a lot of", "few"], 2, "Water is uncountable, so it takes 'a lot of'. 'Many', 'several' and 'few' are used only with countable nouns.", "'Much' and 'a little' are also used with uncountable nouns.", [1674, 1022]),
(S, "On what date did General Qamar Javed Bajwa retire as Chief of Army Staff?", ["29 November 2022", "29 November 2019", "1 December 2022", "28 January 2023"], 0, "General Bajwa retired on 29 November 2022 after six years as army chief. General Asim Munir took over the command.", "His term had been extended by three years in 2019.", [2462]),
(S, "A jet uses 70 gallons of fuel for 320 km. How much fuel will it use for 500 km?", ["100 gallons", "109.375 gallons", "112 gallons", "120 gallons"], 1, "Fuel per km = 70 / 320. For 500 km: 70 x 500 / 320 = 35000 / 320 = 109.375 gallons.", "Fuel use is directly proportional to distance at a constant rate.", [1947]),
(S, "Jhang district is located in which province of Pakistan?", ["Sindh", "Balochistan", "Khyber Pakhtunkhwa", "Punjab"], 3, "Jhang is a city and district in the Punjab province, on the Chenab River.", "The Chenab and Jhelum rivers meet near Trimmu in Jhang district.", [2171, 2391, 645]),
(S, "Which major city is closest to Jhang?", ["Faisalabad", "Quetta", "Peshawar", "Karachi"], 0, "Jhang lies in central Punjab, about 80 km from Faisalabad.", "Faisalabad is the third most populated city of Pakistan.", [2392]),
(S, "Who wrote the Urdu poetry book Bal-e-Jibreel (Gabriel's Wing)?", ["Mirza Ghalib", "Allama Muhammad Iqbal", "Faiz Ahmad Faiz", "Altaf Hussain Hali"], 1, "Bal-e-Jibreel was written by Allama Muhammad Iqbal and published in 1935.", "Iqbal's other Urdu books include Bang-e-Dara and Zarb-e-Kaleem.", [786, 4798, 785, 522]),
(S, "In which year was the Jinnah-Sikandar Pact signed?", ["1916", "1929", "1937", "1940"], 2, "The Jinnah-Sikandar Pact was signed in October 1937 at the Lucknow session of the Muslim League, with Punjab premier Sir Sikandar Hayat Khan.", "Under it the Unionist Party members in Punjab agreed to support the Muslim League in the central assembly.", [3669]),
]
